import React,{useEffect,useState} from 'react';
import {createRoot} from 'react-dom/client';
import ContentAdmin from '../../components/ContentAdmin';
import RestaurantRequest from '../../components/RestaurantRequest';
import NearbyPlaces from '../../components/NearbyPlaces';
import '../../index.css';
const request=location.pathname==='/qa/restaurant';
export function ViewportProof(){const [metric,setMetric]=useState('Measuring viewport…');useEffect(()=>{const measure=()=>setMetric(`Viewport ${document.documentElement.clientWidth}px / content ${document.documentElement.scrollWidth}px`);const observer=new ResizeObserver(measure);observer.observe(document.body);window.addEventListener('resize',measure);measure();return()=>{observer.disconnect();window.removeEventListener('resize',measure);};},[]);return <output className="block bg-white p-2 text-xs font-semibold">{metric}</output>;}
export function GuestDemo(){const [lang,setLang]=useState('tr'),[other,setOther]=useState(false);return <main className="max-w-xl mx-auto p-5"><label>Dil<select aria-label="Test language" value={lang} onChange={e=>setLang(e.target.value)}>{['tr','en','es','ar','zh','de','fr','ru'].map(l=><option key={l}>{l}</option>)}</select></label><button onClick={()=>setOther(v=>!v)} className="min-h-11 p-3 border">Başka restoran</button><RestaurantRequest key={lang+(other?'other':'main')} name={other?'TEST ONLY Other':'TEST ONLY Restaurant'} city="İstanbul" source="https://example.test/restaurant" businessKey={other?'google/ChIJotherTest':'google/ChIJtest123'} lang={lang}/></main>;}
createRoot(document.getElementById('root')!).render(<React.StrictMode><aside style={{padding:12,background:'#fff4d9',fontWeight:700}}>TEST ONLY · Yerel ve geçici veritabanı · Gerçek e-posta gönderilmez</aside><ViewportProof/>{location.pathname==='/qa/discovery'?<main className="max-w-5xl mx-auto p-5"><NearbyPlaces kind="essential" fixedCategory="hotel" lang="tr" center={{lat:41.0082,lng:28.9784}} cityName="İstanbul"/></main>:request?<GuestDemo/>:<ContentAdmin role="admin"/>}</React.StrictMode>);
